mapper.select:
SELECT *
FROM (
  SELECT * FROM CHAT_MESSAGE
  WHERE CHATROOM_ID = #{roomId}

    AND MESSAGE_ID < #{beforeMessageId}

  ORDER BY MESSAGE_ID DESC
)
WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE CHAT_MESSAGE
SET IS_READ = 'Y', READ_AT = CASE WHEN IS_READ='N' THEN SYSTIMESTAMP ELSE READ_AT END
WHERE CHATROOM_ID = #{roomId}
  AND SENDER_ID <> #{readerId}
  AND MESSAGE_ID <= #{upToMessageId}
  AND IS_READ = 'N'

mapper.select:
SELECT COUNT(*)
FROM CHAT_MESSAGE
WHERE CHATROOM_ID = #{roomId}
  AND SENDER_ID <> #{readerId}
  AND IS_READ = 'N'
